public final class ImagePickerActivity extends Activity {
 private final int bg=Color.rgb(16,17,18),panel=Color.rgb(29,37,25),fg=Color.rgb(216,234,205),muted=Color.rgb(142,160,130),green=Color.rgb(198,224,177);
 private final ExecutorService queryWorker=Executors.newSingleThreadExecutor();
 private final ThreadPoolExecutor thumbnails=new ThreadPoolExecutor(3,3,30,TimeUnit.SECONDS,new LinkedBlockingQueue<Runnable>(160),new ThreadPoolExecutor.DiscardOldestPolicy());
 private LruCache<String,Bitmap> cache;private PhotoLibrary library;private PhotoLibrary.Snapshot shownSnapshot;private final PhotoLibrary.Listener libraryListener=this::showSnapshot;
 private final ArrayList<AlbumIndex.Photo> photos=new ArrayList<>();
 private List<AlbumIndex.Album> albums=new ArrayList<>(),shownAlbums=new ArrayList<>();
 private List<AlbumIndex.Photo> shownPhotos=new ArrayList<>();
 private GridView grid;private EditText search;private TextView title,note,status;private Button albumTab,allTab,sizeButton,permissionButton;private PickerAdapter adapter;
 private String selectedAlbum=null;private boolean albumMode=true,large=false,destroyed=false,loaded=false,requesting=false;private int bindingVersion=0;
 private final Set<String> pinnedAlbums=new HashSet<>(),selectedAlbums=new HashSet<>();private LinearLayout selectionBar;private Button pinButton;private TextView selectedCount;

 @Override public void onCreate(Bundle saved){super.onCreate(saved);getWindow().setDecorFitsSystemWindows(false);getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);library=PhotoLibrary.get(this);cache=library.thumbnails;shownSnapshot=library.peek();photos.addAll(shownSnapshot.photos);albums=shownSnapshot.albums;loaded=shownSnapshot.ready;library.listen(libraryListener);large=getPreferences(MODE_PRIVATE).getBoolean("large",false);try{JSONArray a=new JSONArray(getPreferences(MODE_PRIVATE).getString("pinnedAlbums","[]"));for(int i=0;i<a.length();i++)pinnedAlbums.add(a.getString(i));}catch(Exception ignored){}buildUi();getOnBackInvokedDispatcher().registerOnBackInvokedCallback(OnBackInvokedDispatcher.PRIORITY_DEFAULT,()->goBack());if(!canRead()){requestPhotoPermission();}}
 private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private GradientDrawable shape(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(9));return d;}
 private TextView text(String s,int sp,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(color);return t;}
 private Button button(String label){Button b=new Button(this);b.setText(label);b.setTextSize(12);b.setTextColor(fg);b.setAllCaps(false);b.setMinHeight(0);b.setMinimumHeight(0);b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(10),dp(4),dp(10),dp(4));b.setBackground(shape(panel));return b;}
 private void buildUi(){FrameLayout root=new FrameLayout(this);root.setBackgroundColor(bg);LinearLayout column=new LinearLayout(this);column.setOrientation(LinearLayout.VERTICAL);column.setPadding(dp(14),dp(8),dp(14),0);root.addView(column,new FrameLayout.LayoutParams(-1,-1));setContentView(root);root.setOnApplyWindowInsetsListener((view,insets)->{Insets bars=insets.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout()|WindowInsets.Type.ime());view.setPadding(bars.left,bars.top,bars.right,bars.bottom);return WindowInsets.CONSUMED;});root.requestApplyInsets();
  LinearLayout toolbar=new LinearLayout(this);toolbar.setGravity(Gravity.CENTER_VERTICAL);Button back=button("‹ 返回");back.setOnClickListener(v->goBack());toolbar.addView(back,new LinearLayout.LayoutParams(dp(70),dp(38)));title=text("选择图片",18,fg);title.setPadding(dp(12),0,0,0);toolbar.addView(title,new LinearLayout.LayoutParams(0,dp(44),1));title.setGravity(Gravity.CENTER_VERTICAL);Button refresh=button("刷新");refresh.setOnClickListener(v->reload());toolbar.addView(refresh,new LinearLayout.LayoutParams(dp(56),dp(38)));column.addView(toolbar);
  LinearLayout permissions=new LinearLayout(this);permissions.setGravity(Gravity.CENTER_VERTICAL);note=text("正在检查照片权限",11,muted);note.setPadding(0,dp(10),dp(8),dp(10));permissions.addView(note,new LinearLayout.LayoutParams(0,-2,1));permissionButton=button("授权全部");permissionButton.setOnClickListener(v->{if(fullPermission())openSettings();else requestPhotoPermission();});permissions.addView(permissionButton,new LinearLayout.LayoutParams(dp(78),dp(34)));column.addView(permissions);
  LinearLayout tabs=new LinearLayout(this);tabs.setGravity(Gravity.CENTER_VERTICAL);albumTab=button("相册");allTab=button("全部图片");sizeButton=button(large?"标准缩略图":"大缩略图");albumTab.setOnClickListener(v->{selectedAlbums.clear();selectedAlbum=null;albumMode=true;search.setText("");render();});allTab.setOnClickListener(v->{selectedAlbums.clear();selectedAlbum=null;albumMode=false;search.setText("");render();});sizeButton.setOnClickListener(v->{large=!large;getPreferences(MODE_PRIVATE).edit().putBoolean("large",large).apply();sizeButton.setText(large?"标准缩略图":"大缩略图");render();});tabs.addView(albumTab,new LinearLayout.LayoutParams(dp(70),dp(38)));LinearLayout.LayoutParams tabParams=new LinearLayout.LayoutParams(dp(90),dp(38));tabParams.setMargins(dp(8),0,dp(8),0);tabs.addView(allTab,tabParams);tabs.addView(sizeButton,new LinearLayout.LayoutParams(0,dp(38),1));column.addView(tabs);
  selectionBar=new LinearLayout(this);selectionBar.setGravity(Gravity.CENTER_VERTICAL);selectedCount=text("",12,fg);selectionBar.addView(selectedCount,new LinearLayout.LayoutParams(0,dp(43),1));pinButton=button("置顶");pinButton.setOnClickListener(v->{int action=AlbumIndex.pinAction(selectedAlbums,pinnedAlbums);if(action!=1&&action!=2)return;if(action==1)pinnedAlbums.addAll(selectedAlbums);else pinnedAlbums.removeAll(selectedAlbums);getPreferences(MODE_PRIVATE).edit().putString("pinnedAlbums",new JSONArray(pinnedAlbums).toString()).apply();selectedAlbums.clear();render();});selectionBar.addView(pinButton,new LinearLayout.LayoutParams(dp(84),dp(36)));Button cancelSelection=button("取消选择");cancelSelection.setOnClickListener(v->{selectedAlbums.clear();render();});LinearLayout.LayoutParams cancelParams=new LinearLayout.LayoutParams(dp(84),dp(36));cancelParams.setMargins(dp(8),0,0,0);selectionBar.addView(cancelSelection,cancelParams);column.addView(selectionBar);selectionBar.setVisibility(View.GONE);
  search=new EditText(this);search.setTextColor(fg);search.setHintTextColor(muted);search.setSingleLine(true);search.setTextSize(13);search.setPadding(dp(12),0,dp(12),0);search.setBackground(shape(panel));LinearLayout.LayoutParams searchParams=new LinearLayout.LayoutParams(-1,dp(43));searchParams.setMargins(0,dp(12),0,dp(8));column.addView(search,searchParams);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){render();}public void afterTextChanged(Editable e){}});
  status=text("正在读取本机相册…",11,muted);status.setPadding(0,dp(3),0,dp(9));column.addView(status);
  grid=new GridView(this);grid.setHorizontalSpacing(dp(9));grid.setVerticalSpacing(dp(11));grid.setStretchMode(GridView.STRETCH_COLUMN_WIDTH);grid.setClipToPadding(false);grid.setPadding(0,0,0,dp(16));TextView empty=text("没有可显示的图片\n请授予全部照片权限，或尝试刷新。",13,muted);empty.setGravity(Gravity.CENTER);FrameLayout area=new FrameLayout(this);area.addView(grid,new FrameLayout.LayoutParams(-1,-1));area.addView(empty,new FrameLayout.LayoutParams(-1,-1));grid.setEmptyView(empty);column.addView(area,new LinearLayout.LayoutParams(-1,0,1));adapter=new PickerAdapter();grid.setAdapter(adapter);grid.setOnItemClickListener((parent,v,index,id)->{if(albumMode){if(!selectedAlbums.isEmpty()){toggleAlbum(shownAlbums.get(index).key);return;}selectedAlbum=shownAlbums.get(index).key;albumMode=false;search.setText("");render();grid.setSelection(0);}else select(shownPhotos.get(index));});grid.setOnItemLongClickListener((parent,v,index,id)->{if(albumMode){toggleAlbum(shownAlbums.get(index).key);}else preview(index);return true;});updatePermissionNote();render();
 }
 private boolean fullPermission(){return checkSelfPermission("android.permission.READ_MEDIA_IMAGES")==PackageManager.PERMISSION_GRANTED;}
 private boolean canRead(){return fullPermission()||(Build.VERSION.SDK_INT>=34&&checkSelfPermission("android.permission.READ_MEDIA_VISUAL_USER_SELECTED")==PackageManager.PERMISSION_GRANTED);}
 private void updatePermissionNote(){if(note==null)return;note.setText(fullPermission()?"已授权全部照片 · 本机目录相册":canRead()?"仅授权部分照片，相册可能不完整":"需要照片读取权限才能浏览本机相册");note.setTextColor(fullPermission()?muted:Color.rgb(229,185,121));permissionButton.setText(fullPermission()?"权限设置":"授权全部");}
 private void openSettings(){startActivity(new Intent(Settings.ACTION_APPLICATION_DETAILS_SETTINGS,Uri.parse("package:"+getPackageName())));}
 private void requestPhotoPermission(){if(requesting)return;requesting=true;requestPermissions(Build.VERSION.SDK_INT>=34?new String[]{"android.permission.READ_MEDIA_IMAGES","android.permission.READ_MEDIA_VISUAL_USER_SELECTED"}:new String[]{"android.permission.READ_MEDIA_IMAGES"},53);}
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] grants){super.onRequestPermissionsResult(code,permissions,grants);if(code==53){requesting=false;updatePermissionNote();reload();if(!fullPermission())new AlertDialog.Builder(this).setTitle("照片访问范围").setMessage(canRead()?"当前只允许部分照片。要看到完整的本机相册，请在权限设置中选择允许所有照片。":"当前未授予照片读取权限。可在系统权限设置中允许所有照片后继续。").setPositiveButton("权限设置",(d,w)->openSettings()).setNegativeButton("继续",null).show();}}
 @Override protected void onResume(){super.onResume();if(grid!=null&&!requesting){updatePermissionNote();showSnapshot(library.peek());}}
 private void showSnapshot(PhotoLibrary.Snapshot next){if(destroyed||next==shownSnapshot)return;shownSnapshot=next;photos.clear();photos.addAll(next.photos);albums=next.albums;loaded=next.ready;render();if(next.error!=null)status.setText("读取失败，可点击刷新重试");}
 private void reload(){if(destroyed)return;updatePermissionNote();library.refresh();showSnapshot(library.peek());}
 private void render(){if(grid==null)return;String query=search.getText().toString();albumTab.setTextColor(albumMode?green:muted);allTab.setTextColor(!albumMode&&selectedAlbum==null?green:muted);search.setHint(albumMode?"搜索相册名称或目录":"搜索图片文件名");if(albumMode){shownAlbums=AlbumIndex.pinnedFirst(AlbumIndex.filterAlbums(albums,query),pinnedAlbums);title.setText("选择图片");grid.setNumColumns(2);status.setText(loaded?shownAlbums.size()+" 个相册 · "+photos.size()+" 张照片":"正在读取本机相册…");}else{List<AlbumIndex.Photo> source=photos;String name="全部图片";if(selectedAlbum!=null){AlbumIndex.Album selected=null;for(AlbumIndex.Album a:albums)if(a.key.equals(selectedAlbum)){selected=a;break;}if(selected!=null){source=selected.photos;name=selected.name;}else selectedAlbum=null;}shownPhotos=AlbumIndex.filterPhotos(source,query);title.setText(name);grid.setNumColumns(large?2:3);status.setText(shownPhotos.size()+" 张 · 轻点选择，长按预览");}selectionBar.setVisibility(albumMode&&!selectedAlbums.isEmpty()?View.VISIBLE:View.GONE);int action=AlbumIndex.pinAction(selectedAlbums,pinnedAlbums);selectedCount.setText("已选 "+selectedAlbums.size()+" 个相册");pinButton.setText(action==2?"取消置顶":"置顶");pinButton.setEnabled(action==1||action==2);pinButton.setAlpha(action==3?.35f:1f);bindingVersion++;adapter.notifyDataSetChanged();}
 private void select(AlbumIndex.Photo p){try{try(java.io.InputStream in=getContentResolver().openInputStream(Uri.parse(p.uri))){if(in==null)throw new java.io.IOException("无法访问图片");}Intent result=new Intent().setData(Uri.parse(p.uri)).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);setResult(RESULT_OK,result);finish();}catch(Exception e){Toast.makeText(this,"这张图片暂时无法读取，请刷新或调整权限",Toast.LENGTH_LONG).show();}}
 private void toggleAlbum(String key){if(!selectedAlbums.add(key))selectedAlbums.remove(key);grid.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);render();}
 private void preview(int index){ArrayList<AlbumIndex.Photo> items=new ArrayList<>(shownPhotos);PreviewPager pager=new PreviewPager(items,index);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(items.get(index).name).setView(pager).setPositiveButton("使用此图",(d,w)->select(items.get(pager.current))).setNegativeButton("返回",null).create();pager.dialog=dialog;dialog.setOnShowListener(d->{dialog.getWindow().setLayout((int)(getResources().getDisplayMetrics().widthPixels*.96),-2);ViewGroup.LayoutParams params=pager.getLayoutParams();params.height=(int)(getResources().getDisplayMetrics().heightPixels*.64);pager.setLayoutParams(params);pager.post(()->pager.bind());});dialog.setOnDismissListener(d->pager.dispose());dialog.show();}
 private final class PreviewPager extends HorizontalScrollView {
  final ArrayList<AlbumIndex.Photo> items;final LinearLayout row;final ImageView[] pages=new ImageView[3];final Set<String> loading=new HashSet<>();int current,generation,width;float downX;long downAt;boolean settling,clamping;AlertDialog dialog;ValueAnimator settleAnimation;
  PreviewPager(ArrayList<AlbumIndex.Photo> items,int index){super(ImagePickerActivity.this);this.items=items;current=index;setBackgroundColor(Color.BLACK);setHorizontalScrollBarEnabled(false);setOverScrollMode(OVER_SCROLL_NEVER);setFillViewport(false);row=new LinearLayout(ImagePickerActivity.this);row.setOrientation(LinearLayout.HORIZONTAL);addView(row,new HorizontalScrollView.LayoutParams(-2,-1));for(int i=0;i<3;i++){ImageView image=new ImageView(ImagePickerActivity.this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setPadding(dp(6),0,dp(6),0);row.addView(image,new LinearLayout.LayoutParams(1,-1));pages[i]=image;}}
  void bind(){if(dialog==null||!dialog.isShowing()||destroyed)return;width=getWidth();if(width<1){post(()->bind());return;}
   // Snapshot every drawable before reassigning slots: an adjacent page becomes the center.
   Map<String,Drawable> retained=new HashMap<>();for(ImageView image:pages)if(image.getTag() instanceof String&&image.getDrawable()!=null)retained.put((String)image.getTag(),image.getDrawable());
   dialog.setTitle((current+1)+" / "+items.size()+" · "+items.get(current).name);for(int slot=0;slot<3;slot++){ImageView image=pages[slot];image.setLayoutParams(new LinearLayout.LayoutParams(width,-1));int position=current+slot-1;String uri=position>=0&&position<items.size()?items.get(position).uri:null;if(!Objects.equals(uri,image.getTag())){image.setTag(uri);image.setImageDrawable(retained.get(uri));}}
   // Prioritize the visible page; pending decodes follow the URI even if its slot changes.
   for(int slot:new int[]{1,0,2}){ImageView image=pages[slot];if(image.getTag() instanceof String&&image.getDrawable()==null)loadPreview((String)image.getTag());}
   // Recenter in this UI turn, without an empty frame between rebinding and scrolling.
   scrollTo(width,0);post(()->{if(dialog.isShowing()&&!destroyed){scrollTo(width,0);settling=false;}});
  }
  private void loadPreview(String uri){if(!loading.add(uri))return;final int token=generation;queryWorker.execute(()->{Bitmap decoded=null;try{decoded=ImageDecoder.decodeBitmap(ImageDecoder.createSource(getContentResolver(),Uri.parse(uri)),(decoder,info,source)->{decoder.setAllocator(ImageDecoder.ALLOCATOR_SOFTWARE);decoder.setTargetSampleSize(Math.max(1,(int)Math.ceil(Math.max(info.getSize().getWidth(),info.getSize().getHeight())/1600.0)));});}catch(Exception ignored){}final Bitmap bitmap=decoded;runOnUiThread(()->{loading.remove(uri);if(destroyed||!dialog.isShowing()||generation!=token||bitmap==null)return;for(ImageView image:pages)if(uri.equals(image.getTag()))image.setImageBitmap(bitmap);});});}
  private void settle(int shift){settling=true;final int next=current+shift;settleAnimation=ValueAnimator.ofInt(getScrollX(),width*(1+shift));settleAnimation.setDuration(220);settleAnimation.addUpdateListener(animation->scrollTo((Integer)animation.getAnimatedValue(),0));settleAnimation.addListener(new AnimatorListenerAdapter(){@Override public void onAnimationEnd(Animator animation){if(!destroyed&&dialog.isShowing()){current=next;bind();}}});settleAnimation.start();}
  void dispose(){generation++;if(settleAnimation!=null){settleAnimation.removeAllListeners();settleAnimation.removeAllUpdateListeners();settleAnimation.cancel();}loading.clear();}
  @Override public boolean onTouchEvent(MotionEvent e){if(settling)return true;if(e.getActionMasked()==MotionEvent.ACTION_DOWN){downX=e.getX();downAt=e.getEventTime();}if(e.getActionMasked()==MotionEvent.ACTION_UP||e.getActionMasked()==MotionEvent.ACTION_CANCEL){MotionEvent cancel=MotionEvent.obtain(e);cancel.setAction(MotionEvent.ACTION_CANCEL);super.onTouchEvent(cancel);cancel.recycle();float travel=downX-e.getX(),speed=travel/Math.max(1,e.getEventTime()-downAt);int shift=0;if(e.getActionMasked()==MotionEvent.ACTION_UP&&(Math.abs(getScrollX()-width)>width*.18f||(Math.abs(travel)>dp(28)&&Math.abs(speed)>.45f)))shift=travel>0?1:-1;shift=Math.max(-current,Math.min(items.size()-1-current,shift));settle(shift);return true;}return super.onTouchEvent(e);}
  @Override protected void onScrollChanged(int x,int y,int oldX,int oldY){super.onScrollChanged(x,y,oldX,oldY);if(width<=0||clamping)return;int bounded=Math.max(current==0?width:0,Math.min(current==items.size()-1?width:width*2,x));if(bounded!=x){clamping=true;scrollTo(bounded,0);clamping=false;}}
 }
 private void goBack(){if(!selectedAlbums.isEmpty()){selectedAlbums.clear();render();return;}if(!albumMode&&selectedAlbum!=null){selectedAlbum=null;albumMode=true;search.setText("");render();}else finish();}
 private final class PickerAdapter extends BaseAdapter {
  public int getCount(){return albumMode?shownAlbums.size():shownPhotos.size();}public Object getItem(int position){return albumMode?shownAlbums.get(position):shownPhotos.get(position);}public long getItemId(int position){return position;}
  public View getView(int position,View recycled,android.view.ViewGroup parent){LinearLayout tile;ImageView image;TextView label,detail;if(recycled instanceof LinearLayout){tile=(LinearLayout)recycled;image=(ImageView)tile.getChildAt(0);label=(TextView)tile.getChildAt(1);detail=(TextView)tile.getChildAt(2);}else{tile=new LinearLayout(ImagePickerActivity.this);tile.setOrientation(LinearLayout.VERTICAL);tile.setBackground(shape(panel));image=new ImageView(ImagePickerActivity.this);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackgroundColor(Color.rgb(38,47,33));tile.addView(image);label=text("",12,fg);label.setPadding(dp(8),dp(7),dp(8),dp(2));label.setMaxLines(1);label.setEllipsize(TextUtils.TruncateAt.END);tile.addView(label,new LinearLayout.LayoutParams(-1,dp(29)));detail=text("",9,muted);detail.setPadding(dp(8),0,dp(8),dp(6));detail.setMaxLines(1);detail.setEllipsize(TextUtils.TruncateAt.MIDDLE);tile.addView(detail,new LinearLayout.LayoutParams(-1,dp(22)));}
   int columns=albumMode?2:large?2:3;int width=Math.max(dp(70),(getResources().getDisplayMetrics().widthPixels-dp(28)-dp(9)*(columns-1))/columns);image.setLayoutParams(new LinearLayout.LayoutParams(-1,width));AlbumIndex.Photo photo;if(albumMode){AlbumIndex.Album album=shownAlbums.get(position);photo=album.photos.get(0);label.setText((selectedAlbums.isEmpty()?"":selectedAlbums.contains(album.key)?"☑ ":"☐ ")+(pinnedAlbums.contains(album.key)?"↑ ":"")+album.name+" · "+album.photos.size());tile.setBackground(shape(selectedAlbums.contains(album.key)?Color.rgb(60,80,45):panel));detail.setText((pinnedAlbums.contains(album.key)?"已置顶 · ":"")+(album.path.isEmpty()?album.volume:album.path));}else{tile.setBackground(shape(panel));photo=shownPhotos.get(position);label.setText(photo.name);detail.setText(photo.width+" × "+photo.height);}String key=photo.uri+"@"+width;image.setTag(key);Bitmap existing=cache.get(key);image.setImageBitmap(existing);if(existing==null){final ImageView target=image;final String tag=key;final int version=bindingVersion;thumbnails.execute(()->{if(destroyed||version!=bindingVersion)return;try{Bitmap bitmap=getContentResolver().loadThumbnail(Uri.parse(photo.uri),new Size(width,width),null);cache.put(tag,bitmap);runOnUiThread(()->{if(!destroyed&&tag.equals(target.getTag()))target.setImageBitmap(bitmap);});}catch(Exception ignored){}});}return tile;}
 }
 @Override protected void onDestroy(){destroyed=true;library.unlisten(libraryListener);queryWorker.shutdownNow();thumbnails.shutdownNow();super.onDestroy();}
}
